CREATE TABLE IF NOT EXISTS social_conversations (id TEXT PRIMARY KEY,channel TEXT NOT NULL,external_thread_id TEXT NOT NULL,lead_id TEXT NOT NULL DEFAULT '',contact_name TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'open',metadata_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(channel, external_thread_id));
CREATE TABLE IF NOT EXISTS social_messages (id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL,channel TEXT NOT NULL,external_message_id TEXT NOT NULL,direction TEXT NOT NULL,sender_id TEXT NOT NULL DEFAULT '',body TEXT NOT NULL DEFAULT '',payload_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL,UNIQUE(channel, external_message_id));
